-- The Digital Marketing plan's footage items already open take the 48-hour First edit (R78), as new plans do.
UPDATE "engagement_tasks" SET "turnaround" = 'first_edit'
WHERE "turnaround" IS NULL AND "kind" = 'action' AND "side" = 'client' AND "title" LIKE 'Send week % footage'
  AND "engagementId" IN (SELECT "id" FROM "engagements" WHERE "type" = 'digital_marketing');